def merge_sorted_streams(*streams):
    iterators = [iter(s) for s in streams]
    heads = {}
    for idx, it in enumerate(iterators):
        try:
            heads[idx] = next(it)
        except StopIteration:
            pass

    while heads:
        min_key = min(k for k, v in heads.values())
        merged_value = None
        for idx in sorted(heads):
            key, value = heads[idx]
            if key == min_key:
                merged_value = value
                try:
                    heads[idx] = next(iterators[idx])
                except StopIteration:
                    del heads[idx]
        if merged_value is not None:
            yield (min_key, merged_value)
